public static int findNthLeapYear(int Y, int N) {
  if (Y < 0) return -1;
  if (N < 0) return -1;

  Queue<Integer> que = new LinkedList<>();
  for (int i = Y; i <= Y + N - 1; i++) {
    que.offer(i);
  }

  int count = 0;

  while (!que.isEmpty()) {
    int year = que.poll();
    if (count++ == N) {
      return year;
